var e = $input.first().json.data || $input.first().json;
var decision = String(e.evaluationDecision || '').toLowerCase();
var counter = Number(e.counterofferAmount);
var current = Number(e.currentOfferAmount || 0);
var mao = Number(e.protectedMAO);
var dealStatus = String(e.dealStatus || '').toLowerCase();
var suppressed = e.suppressed === true || e.dnc === true;
var human = e.humanReviewRequired === true || decision === 'human_review';
var proposed = decision === 'revised_offer' ? Math.min(mao, counter > 0 && current > 0 ? Math.round(((counter + current) / 2) * 100) / 100 : 0) : decision === 'accept_or_contract' ? counter : 0;
var action = decision === 'accept_or_contract' ? 'accept_or_contract' : decision === 'revised_offer' ? 're_offer' : decision === 'walk_away_or_reengage' ? 're_engage' : 'human_review';
var validAmount = Number.isFinite(proposed) && proposed > 0;
var protectedState = ['closed','cancelled','disputed'].indexOf(dealStatus) !== -1;
var blocked = human || suppressed || protectedState || !Number.isFinite(mao) || mao <= 0 || (action === 're_offer' && (!validAmount || proposed > mao));
var blockedReason = human ? 'human_review_required' : suppressed ? 'seller_suppressed_or_dnc' : protectedState ? 'deal_state_protected' : !Number.isFinite(mao) || mao <= 0 ? 'missing_protected_mao' : action === 're_offer' && (!validAmount || proposed > mao) ? 'invalid_or_excessive_re_offer' : null;
return [{ json: { ...e, evaluationDecision: decision, negotiationAction: action, proposedOfferAmount: proposed, blocked: blocked, blockedReason: blockedReason, idempotencyKey: 'wf376:' + String(e.evaluationId || e.activityId || '') + ':' + action + ':' + String(proposed) } }];
